create procedure MM_SP_ConsultaRegistroGastoPorFactura --18404	@IdFactura INT,	/*--------------------parametros contrato  --------------------*/    @IdContrato    INT = null,    @IdUsuario     INT = null,    @FechaRegistro DATETIME = null	/*-------------------------------------------------------------*/ASBEGIN	SELECT r.IdRegistro	FROM dbo.CO_Registro r	WHERE r.IdFactura = @IdFacturaEND